
export const getVariablesAndQueryConfig = (
    {
        org_id: {key, value},
        source,
    }
) => {
    //<editor-fold desc="variables, filters">
    const variables = {
        [key]: value,
        // removed,
    };

    let filter = ``;
    if (source) {
        filter = `source: {_eq: "${source}"}`;
    }

    if(!filter.isEmpty()) {
        filter = `, ${filter}`;
    }
    //</editor-fold>

    return {variables, filter};
};