import listAllNCRByLoggedImpl from "./listAllNCRByLoggedImpl";

export const byCompany = (
    {
        company_id,
        source,
    }
) => {
    return listAllNCRByLoggedImpl({
        org_id: {key: 'company_id', value: company_id},
        source,
    });
};

